const q=s=>document.querySelector(s), qa=s=>[...document.querySelectorAll(s)], root=q('#app');
const initial={demoMode:false,
 dependencies:['Dirección de Desarrollo Social','Dirección de Obras Públicas','Instituto Municipal de la Mujer'],
 systemAccounts:[{id:'admin',role:'Administrador',name:'Jorge Gutiérrez',username:'admin.pmd',password:'AdminPMD2026!'},{id:'finance',role:'Finanzas',name:'Jorge Soto',username:'finanzas.pmd',password:'FinanzasPMD2026!'},{id:'superadmin',role:'Super Admin',name:'Soporte de Sistemas',username:'superadmin.pmd',password:'SoportePMD2026!'}],
 users:[],
 centers:[{id:1,code:'CC-110',name:'Desarrollo social',ceiling:420000},{id:2,code:'CC-111',name:'Capacitación y empleo',ceiling:600000},{id:3,code:'CC-210',name:'Infraestructura urbana',ceiling:1800000},{id:4,code:'CC-211',name:'Alumbrado público',ceiling:900000},{id:5,code:'CC-310',name:'Atención a las mujeres',ceiling:350000}],
 axes:[{code:'1',name:'Bienestar y desarrollo social',objectives:[{code:'1.1',name:'Mejorar oportunidades de desarrollo de la juventud',strategies:[{code:'1.1.1',name:'Impulsar la formación y vinculación laboral',lineIds:[1,2]}]},{code:'1.2',name:'Fortalecer la infraestructura urbana',strategies:[{code:'1.2.1',name:'Mejorar espacios públicos prioritarios',lineIds:[3,4]}]}]},{code:'2',name:'Igualdad sustantiva y vida libre de violencia',objectives:[{code:'2.1',name:'Garantizar atención integral a las mujeres',strategies:[{code:'2.1.1',name:'Fortalecer los servicios de prevención y atención',lineIds:[5]}]}]}],
 lines:[
  {id:1,code:'1.1.1.1',name:'Implementar talleres de empleabilidad para jóvenes',objective:'1.1',strategy:'1.1.1',dep:'Dirección de Desarrollo Social',status:'Sin asignar',centerId:null,budget:0},
  {id:2,code:'1.1.1.2',name:'Vincular a jóvenes con oportunidades de empleo formal',objective:'1.1',strategy:'1.1.1',dep:'Dirección de Desarrollo Social',status:'Rechazada',reason:'La dependencia requiere ajustar la capacidad operativa y el calendario de vinculación antes de comprometer esta acción.',rejectionHistory:[{name:'María López',username:'m.lopez',dependency:'Dirección de Desarrollo Social',reason:'La dependencia requiere ajustar la capacidad operativa y el calendario de vinculación antes de comprometer esta acción.',at:'10 de septiembre de 2026, 10:00'}],centerId:null,budget:0},
  {id:3,code:'1.2.1.1',name:'Rehabilitar espacios públicos prioritarios',objective:'1.2',strategy:'1.2.1',dep:'Dirección de Obras Públicas',status:'Aceptada',centerId:3,budget:1250000},
  {id:4,code:'1.2.1.2',name:'Instalar luminarias eficientes en colonias',objective:'1.2',strategy:'1.2.1',dep:'Dirección de Obras Públicas',status:'Aceptada',centerId:4,budget:680000},
  {id:5,code:'2.1.1.1',name:'Brindar atención integral a mujeres en situación de violencia',objective:'2.1',strategy:'2.1.1',dep:'Instituto Municipal de la Mujer',status:'Sin asignar',centerId:null,budget:0}
 ],programs:{'1.1':'PP-01 Desarrollo de Capacidades Juveniles','1.2':'PP-02 Infraestructura para el Bienestar','2.1':''},sheets:{}};
if(window.PMD_REAL_STRUCTURE){initial.dependencies=window.PMD_REAL_STRUCTURE.dependencies;initial.dependencyCatalog=window.PMD_REAL_STRUCTURE.dependencyCatalog;initial.axes=window.PMD_REAL_STRUCTURE.axes;initial.lines=window.PMD_REAL_STRUCTURE.lines;initial.programCatalog=window.PMD_REAL_STRUCTURE.programCatalog;initial.programs={}}
let data=JSON.parse(localStorage.getItem('pmd-guadalupe-real-v2')||JSON.stringify(initial));
data.systemAccounts=data.systemAccounts||initial.systemAccounts;
data.users=data.users.map(u=>({...u,username:u.username||u.mail.split('@')[0]}));
let role='',view='dashboard',picked=[],session=null;
const persist=()=>localStorage.setItem('pmd-guadalupe-real-v2',JSON.stringify(data));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const findLine=id=>data.lines.find(x=>x.id===Number(id)); const cc=id=>data.centers.find(x=>x.id===Number(id));
const badge=s=>`<span class="badge ${s==='Aceptada'?'green':s==='Rechazada'?'red':s==='Activo'?'blue':'orange'}">${s}</span>`;
function notice(msg){let t=q('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function openModal(title,body,save,action='Guardar',kind=''){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><section class="modal ${kind}"><h2>${title}</h2>${body}<div class="modal-actions"><button class="outline close-modal">Cancelar</button><button class="primary confirm-modal">${action}</button></div></section></div>`);q('.close-modal').onclick=()=>q('.modal-backdrop').remove();q('.confirm-modal').onclick=()=>{if(save()!==false)q('.modal-backdrop').remove()}}
function login(){root.innerHTML=`<div class="login guadalupe-login"><section class="login-hero"><div class="hero-copy"><div class="hero-pmd">PMD</div><span class="eyebrow">Gobierno Municipal de Guadalupe</span><h1>Un Gobierno cercano que transforma Guadalupe.</h1><p>Accede con tus credenciales para dar seguimiento al Plan Municipal de Desarrollo, sus responsabilidades y presupuesto.</p><div class="steps"><div class="step">01<br><b>Planeación</b></div><div class="step">02<br><b>Seguimiento</b></div><div class="step">03<br><b>Resultados</b></div></div></div></section><section class="login-form"><div class="form-card login-card"><img class="gov-logo" src="logo-guadalupe-transparent.png" alt="Guadalupe Gobierno Municipal"><h2>Acceso al sistema PMD</h2><p>Ingresa tu usuario y contraseña asignados.</p><form id="loginForm"><label>Usuario</label><input id="loginUser" autocomplete="username" placeholder="Ej. admin.pmd" required><label>Contraseña</label><div class="password-field"><input id="loginPass" type="password" autocomplete="current-password" placeholder="Escribe tu contraseña" required><button type="button" id="showPass" aria-label="Mostrar contraseña">◉</button></div><p class="login-error" id="loginError" aria-live="polite"></p><button class="primary full" type="submit">Ingresar al sistema →</button></form><details class="demo-access"><summary>Credenciales de demostración</summary><div><b>Admin:</b> admin.pmd · AdminPMD2026!<br><b>Finanzas:</b> finanzas.pmd · FinanzasPMD2026!<br><b>Super Admin:</b> superadmin.pmd · SoportePMD2026!<br>${data.users.length?data.users.map(u=>`<b>Enlace:</b> ${esc(u.username)} · ${esc(u.password)}`).join('<br>'):'<i>Aún no hay usuarios enlace registrados.</i>'}</div></details></div></section></div>`;q('#loginForm').onsubmit=e=>{e.preventDefault();authenticate(q('#loginUser').value.trim(),q('#loginPass').value)};q('#showPass').onclick=()=>{let input=q('#loginPass');input.type=input.type==='password'?'text':'password'}}
function authenticate(username,password){let system=data.systemAccounts.find(a=>a.username.toLowerCase()===username.toLowerCase()&&a.password===password);let enlace=data.users.find(a=>(a.username.toLowerCase()===username.toLowerCase()||a.mail.toLowerCase()===username.toLowerCase())&&a.password===password);let account=system||enlace;if(!account){q('#loginError').textContent='Usuario o contraseña incorrectos.';return}let accountRole=system?system.role:'Enlace';role=accountRole==='Super Admin'?'Admin':accountRole;session={...account,role,accountRole};view=nav[role][0][0];renderApp()}
const nav={Admin:[['dashboard','Inicio','▦'],['catalog','Catálogo PMD','⌘'],['enlaces','Enlaces y dependencias','♙']],Enlace:[['tree','Estructura asignada','⌘'],['accepted','Centros y fichas','✓']],Finanzas:[['finance','PMD publicado','⌘'],['centers','Centros de costo','◎'],['budget','Programas y presupuesto','$']]};
const titles={dashboard:'Panel de control',catalog:'Catálogo PMD',enlaces:'Enlaces y dependencias',tree:'Estructura PMD asignada',accepted:'Centros y fichas técnicas',finance:'PMD publicado',centers:'Centros de costo',budget:'Programas y presupuesto'};
function renderApp(){if(!nav[role].some(n=>n[0]===view))view=nav[role][0][0];const visibleRole=session.accountRole||role;root.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">G</span> PMD</div><div class="role-chip">Sesión activa · <b>${visibleRole}</b></div><nav><div class="nav-label">Navegación</div>${nav[role].map(([id,label,icon])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}"><span class="ico">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot"><button class="logout" id="logout">↪ Cerrar sesión</button></div></aside><main class="main"><header class="topbar"><div class="crumb">PMD / <strong>${titles[view]}</strong></div><div class="profile"><div class="avatar">${session.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><span>${esc(session.name)}<br><small style="color:#69778d">${visibleRole}</small></span></div></header><section class="content" id="content"></section></main></div>`;qa('.nav-item').forEach(b=>b.onclick=()=>{view=b.dataset.view;renderApp()});q('#logout').onclick=()=>{role='';session=null;view='dashboard';login()};renderView()}
function head(title,sub,cta=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${cta}</div>`}
function renderView(){let c=q('#content');if(view==='dashboard')c.innerHTML=dashboard();if(view==='catalog')c.innerHTML=catalog();if(view==='enlaces')c.innerHTML=enlaces();if(view==='tree')c.innerHTML=enlaceTree();if(view==='accepted')c.innerHTML=accepted();if(view==='finance')c.innerHTML=finance();if(view==='centers')c.innerHTML=centers();if(view==='budget')c.innerHTML=budget();bind()}
function dashboard(){let ready=data.lines.filter(x=>x.status==='Aceptada').length;return head('Panel de control','Resumen de la planeación estratégica municipal',`<button class="primary go-catalog">Gestionar catálogo</button>`)+`<div class="metrics"><div class="metric"><div class="metric-top">Ejes estratégicos <span class="metric-icon">⌘</span></div><div class="metric-value">${data.axes.length}</div></div><div class="metric"><div class="metric-top">Líneas de acción <span class="metric-icon">☷</span></div><div class="metric-value">${data.lines.length}</div></div><div class="metric"><div class="metric-top">Pendientes de respuesta <span class="metric-icon">◎</span></div><div class="metric-value">${data.lines.filter(x=>x.status==='Sin asignar').length}</div></div><div class="metric"><div class="metric-top">Aceptadas <span class="metric-icon">✓</span></div><div class="metric-value">${ready}</div></div></div><div class="grid-2"><div class="panel"><h3>Actividad reciente</h3><p class="panel-sub">Movimientos en el PMD</p><div class="activity"><i class="dot green"></i><span><b>${ready} líneas están listas para presupuestarse</b><small>Cuentan con validación y centro de costo</small></span></div><div class="activity"><i class="dot orange"></i><span><b>Validaciones pendientes</b><small>Los enlaces deben aceptar o rechazar sus líneas</small></span></div><div class="activity"><i class="dot"></i><span><b>Catálogo centralizado</b><small>Estructura PMD y asignaciones en una pantalla</small></span></div></div><div class="panel"><h3>Reglas del flujo</h3><p class="panel-sub">Control automático entre perfiles</p><div class="progress-row"><label>Centro de costo asignado antes de presupuesto</label><div class="bar"><i style="width:100%;background:#139a8d"></i></div></div><div class="progress-row"><label>Presupuesto máximo por centro de costo</label><div class="bar"><i style="width:100%;background:#3867e8"></i></div></div><div class="progress-row"><label>Ficha técnica antes de PDF</label><div class="bar"><i style="width:100%;background:#e99b25"></i></div></div></div></div>`}
function linesOf(strategy){return strategy.lineIds.map(findLine).filter(Boolean)}
function pivot(){return data.axes.map(axis=>`<details class="pivot axis" open><summary><span class="chevron">›</span><span class="pivot-code">${axis.code}</span><b>${esc(axis.name)}</b><small>${axis.objectives.length} objetivo(s)</small><button class="mini-btn add-node" data-kind="objective" data-parent="${axis.code}">＋ Objetivo</button></summary><div class="pivot-body">${axis.objectives.map(obj=>`<details class="pivot objective" open><summary><span class="chevron">›</span><span class="pivot-code">${obj.code}</span><b>${esc(obj.name)}</b><small>${obj.strategies.length} estrategia(s)</small><button class="mini-btn add-node" data-kind="strategy" data-parent="${obj.code}">＋ Estrategia</button></summary><div class="pivot-body">${obj.strategies.map(st=>`<details class="pivot strategy" open><summary><span class="chevron">›</span><span class="pivot-code">${st.code}</span><b>${esc(st.name)}</b><small>${st.lineIds.length} línea(s)</small><button class="mini-btn add-node" data-kind="line" data-parent="${st.code}">＋ Línea</button></summary><div class="pivot-body line-list">${linesOf(st).map(line=>`<article class="pivot-line"><span class="pivot-code">${line.code}</span><span class="line-name">${esc(line.name)}</span><span>${badge(line.status)}</span><span class="line-dep">${line.dep||'Sin dependencia'}</span><button class="outline edit-line" data-id="${line.id}">Asignar</button></article>`).join('')||'<p class="empty">Sin líneas de acción.</p>'}</div></details>`).join('')}</div></details>`).join('')}</div></details>`).join('')}
function catalog(){return head('Catálogo PMD','Una única estructura jerárquica para crear, consultar y asignar el plan',`<div class="section-toolbar"><button class="outline tree-toggle" data-mode="open">Expandir todo</button><button class="outline tree-toggle" data-mode="close">Comprimir todo</button><button class="outline add-node" data-kind="axis">＋ Eje</button><button class="primary add-node" data-kind="line">＋ Línea de acción</button></div>`)+`<div class="catalog-note"><b>Vista pivote:</b> expande o comprime Ejes, Objetivos, Estrategias y Líneas de acción. Cada línea conserva su estatus y responsable.</div><div class="status-legend">${badge('Sin asignar')} ${badge('Aceptada')} ${badge('Rechazada')}</div><section class="pivot-wrap">${pivot()}</section><section class="assignment-box"><div><h3>Asignar líneas a dependencia</h3><p>Selecciona una o varias líneas; el enlace de la dependencia podrá responderlas.</p></div><div class="assign-controls"><select id="assignDep"><option value="">Selecciona una dependencia</option>${data.dependencies.map(d=>`<option>${esc(d)}</option>`).join('')}</select><button class="primary" id="assignSelected">Asignar seleccionadas</button></div><div class="assign-lines">${data.lines.map(x=>`<label><input class="line-check" data-id="${x.id}" type="checkbox" ${picked.includes(x.id)?'checked':''}><span class="pivot-code">${x.code}</span> ${esc(x.name)} <em>${x.dep||'Sin dependencia'}</em></label>`).join('')}</div></section>`}
function enlaces(){return head('Enlaces y dependencias','Da de alta accesos individuales y asigna un enlace responsable por dependencia',`<button class="primary" id="addUser">＋ Crear usuario enlace</button>`)+`<div class="two-col"><div class="table-wrap"><table><thead><tr><th>Enlace</th><th>Usuario</th><th>Dependencia</th><th>Correo</th><th>Contraseña temporal</th><th></th></tr></thead><tbody>${data.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td><code class="password-chip">${esc(u.username)}</code></td><td>${esc(u.dep)}</td><td>${esc(u.mail)}</td><td><code class="password-chip">${esc(u.password)}</code></td><td><button class="danger del-user" data-id="${u.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div><section class="panel"><h3>Asignación por dependencia</h3><p class="panel-sub">Cada dependencia debe tener un enlace para recibir líneas de acción.</p>${data.dependencies.map(dep=>{let u=data.users.find(x=>x.dep===dep);return `<div class="dep-link"><span>⌂ <b>${esc(dep)}</b></span><small>${u?`${esc(u.name)} · ${esc(u.username)}`:'Sin enlace asignado'}</small></div>`}).join('')}<button class="outline" id="addDep" style="margin-top:12px">＋ Nueva dependencia</button></section></div>`}
function ownLines(){return data.lines.filter(x=>x.dep===session.dep)}
function enlaceTree(){let rows=ownLines();return head('Estructura PMD asignada','Responde las líneas remitidas a Dirección de Desarrollo Social')+`<div class="two-col"><section class="pivot-wrap compact"><details class="pivot axis" open><summary><span class="chevron">›</span><span class="pivot-code">1</span><b>Bienestar y desarrollo social</b></summary><div class="pivot-body">${rows.map(x=>`<article class="pivot-line"><span class="pivot-code">${x.code}</span><span class="line-name">${esc(x.name)}</span>${badge(x.status)}<button class="outline review" data-id="${x.id}">${x.status==='Sin asignar'?'Responder':'Ver respuesta'}</button></article>`).join('')}</div></details></section><section class="panel"><h3>Acciones del enlace</h3><p class="panel-sub">Acepta si tu dependencia puede atender la línea; al rechazar, el motivo es obligatorio.</p><div class="activity"><i class="dot orange"></i><span>Una línea aceptada debe tener centro de costo antes de ser presupuestada.</span></div><div class="activity"><i class="dot"></i><span>El presupuesto permanece bloqueado para Finanzas mientras no se asigne el centro de costo.</span></div></section></div>`}
function centerName(id){let c=cc(id);return c?`${c.code} · ${c.name}`:'Sin centro de costo'}
function accepted(){let lines=ownLines().filter(x=>x.status==='Aceptada');let linked=[...new Set(lines.map(x=>x.centerId).filter(Boolean))].map(cc);let free=data.centers.filter(c=>!data.lines.some(l=>l.centerId===c.id));return head('Centros y fichas técnicas','Asigna un centro de costo a cada línea aceptada y completa su ficha antes de verla en PDF')+`<div class="cc-metrics"><div class="cc-tile"><small>Centros de costo con líneas</small><b>${linked.length}</b><span>${linked.length?linked.map(c=>`${c.code} · ${c.name}`).join(' | '):'Aún no hay centros vinculados'}</span></div><div class="cc-tile"><small>Centros sin líneas asignadas</small><b>${free.length}</b><span>${free.length?free.map(c=>`${c.code} · ${c.name}`).join(' | '):'Todos cuentan con líneas'}</span></div><div class="cc-tile"><small>Líneas listas para Finanzas</small><b>${lines.filter(x=>x.centerId).length}</b><span>Con centro de costo asignado</span></div></div><div class="two-col"><div>${lines.length?lines.map(x=>`<article class="accepted-card"><h4><span class="pivot-code">${x.code}</span> ${esc(x.name)}</h4><p>${x.centerId?`Centro asignado: <b>${centerName(x.centerId)}</b>`:'Aún no se ha asignado centro de costo.'}</p><div class="line-actions"><button class="outline set-center" data-id="${x.id}">⌂ ${x.centerId?'Cambiar':'Asignar'} centro</button>${x.centerId?(data.sheets[x.id]?`<button class="success pdf" data-id="${x.id}">▣ Ver ficha técnica PDF</button>`:`<button class="primary sheet" data-id="${x.id}">Completar ficha técnica</button>`):''}</div></article>`).join(''):'<div class="empty">Acepta una línea desde “Estructura asignada” para continuar.</div>'}</div><section class="panel"><h3>Catálogo disponible</h3><p class="panel-sub">El catálogo muestra los centros dados de alta por Finanzas. Al seleccionarlo, se vincula únicamente con esta línea de acción asignada.</p>${data.centers.map(c=>`<div class="cc-list"><b>${c.code}</b><span>${esc(c.name)}</span><small>$${c.ceiling.toLocaleString('es-MX')} techo</small></div>`).join('')}</section></div>`}
function finance(){return head('PMD publicado','Estructura estratégica aprobada para programación presupuestaria')+`<section class="pivot-wrap readonly">${pivot()}</section><div class="catalog-note">Consulta la estructura. Los centros de costo y presupuestos se gestionan desde las opciones del menú.</div>`}
function canLoadCenters(){let d=new Date(),m=d.getMonth(),day=d.getDate();return data.demoMode||(m===11&&day>=25)||(m===0&&day<=7)}
function usedCenter(cId,except=0){return data.lines.filter(x=>x.centerId===cId&&x.id!==Number(except)).reduce((sum,x)=>sum+Number(x.budget||0),0)}
function centers(){let permitted=canLoadCenters();return head('Centros de costo','Catálogo anual cargado por Finanzas durante la última semana de diciembre y primera de enero',`<button class="primary" id="addCenter" ${permitted?'':'disabled'}>＋ Dar de alta centro</button>`)+`<div class="cycle-banner ${permitted?'active':''}"><b>${permitted?'Carga habilitada en ambiente de demostración':'Carga cerrada'}</b><span>Periodo de operación: 26 de diciembre al 7 de enero. Fuera de ese periodo, el catálogo queda solo consulta.</span></div><div class="table-wrap"><table><thead><tr><th>Centro de costo</th><th>Techo presupuestal</th><th>Asignado a líneas</th><th>Disponible</th><th></th></tr></thead><tbody>${data.centers.map(c=>{let used=usedCenter(c.id);return `<tr><td><b>${c.code}</b><br><small>${esc(c.name)}</small></td><td>$${c.ceiling.toLocaleString('es-MX')}</td><td>$${used.toLocaleString('es-MX')}</td><td class="${c.ceiling-used<0?'over':''}"><b>$${(c.ceiling-used).toLocaleString('es-MX')}</b></td><td><button class="danger del-center" data-id="${c.id}">Eliminar</button></td></tr>`}).join('')}</tbody></table></div>`}
function objectives(){return data.axes.flatMap(a=>a.objectives)}
function budget(){let eligible=data.lines.filter(x=>x.status==='Aceptada'&&x.centerId);let locked=data.lines.filter(x=>x.status==='Aceptada'&&!x.centerId);let allObj=objectives();let total=eligible.reduce((s,x)=>s+x.budget,0);return head('Programas y presupuesto','Un objetivo equivale a un programa presupuestario. Cada línea no puede superar el techo disponible de su centro.',`<button class="primary" id="savePrograms">Guardar programas</button>`)+`<div class="two-col"><section class="panel"><h3>Programas presupuestarios</h3><p class="panel-sub">Un registro por objetivo.</p>${allObj.map(o=>`<div class="progress-row"><label><b>Objetivo ${o.code}</b><small>${esc(o.name)}</small></label><input class="program" data-id="${o.code}" value="${esc(data.programs[o.code]||'')}" placeholder="Nombre del programa presupuestario"></div>`).join('')}</section><section class="panel"><h3>Presupuesto asignado</h3><p class="panel-sub">En líneas con centro de costo vinculado.</p><div class="metric-value">$${total.toLocaleString('es-MX')}</div><div class="progress-row"><label><span>Regla aplicada</span><b>Techo por CC</b></label><div class="bar"><i style="width:100%;background:#139a8d"></i></div></div></section></div><section class="budget-section"><h3>Líneas habilitadas para presupuesto</h3><div class="table-wrap"><table><thead><tr><th>Línea de acción</th><th>Centro de costo</th><th>Programa</th><th>Disponible en CC</th><th>Presupuesto de línea</th></tr></thead><tbody>${eligible.map(x=>{let c=cc(x.centerId),available=c.ceiling-usedCenter(c.id,x.id);return `<tr><td><b class="pivot-code">${x.code}</b> ${esc(x.name)}</td><td>${centerName(c.id)}</td><td>${esc(data.programs[x.objective]||x.programName||'Pendiente')}</td><td>$${available.toLocaleString('es-MX')}</td><td><input class="money-input budget-input" data-id="${x.id}" type="number" min="0" max="${available}" value="${x.budget}" step="1000"> MXN</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No hay líneas con centro de costo asignado.</td></tr>'}</tbody></table></div></section>${locked.length?`<section class="locked-section"><h3>Bloqueadas hasta asignar centro de costo</h3>${locked.map(x=>`<div><span>🔒</span> <b>${x.code}</b> ${esc(x.name)} <small>El enlace debe asignar centro de costo.</small></div>`).join('')}</section>`:''}`}
function nodeForm(kind,parent=''){let label={axis:'Eje',objective:'Objetivo',strategy:'Estrategia',line:'Línea de acción'}[kind];let options='';if(kind==='objective')options=`<label>Eje padre</label><select id="nodeParent">${data.axes.map(x=>`<option value="${x.code}" ${x.code===parent?'selected':''}>${x.code} · ${esc(x.name)}</option>`).join('')}</select>`;if(kind==='strategy')options=`<label>Objetivo padre</label><select id="nodeParent">${objectives().map(x=>`<option value="${x.code}" ${x.code===parent?'selected':''}>${x.code} · ${esc(x.name)}</option>`).join('')}</select>`;if(kind==='line')options=`<label>Estrategia padre</label><select id="nodeParent">${data.axes.flatMap(a=>a.objectives).flatMap(o=>o.strategies).map(x=>`<option value="${x.code}" ${x.code===parent?'selected':''}>${x.code} · ${esc(x.name)}</option>`).join('')}</select>`;openModal(`Crear ${label}`,`<p>La nomenclatura se genera automáticamente según la estructura seleccionada.</p>${options}<label>Nombre</label><input id="nodeName" placeholder="Escribe el nombre de ${label.toLowerCase()}">`,()=>{let name=q('#nodeName').value.trim();if(!name){notice('Escribe un nombre para continuar.');return false}let p=q('#nodeParent')?.value;if(kind==='axis'){let code=String(Math.max(...data.axes.map(x=>+x.code),0)+1);data.axes.push({code,name,objectives:[]})}if(kind==='objective'){let a=data.axes.find(x=>x.code===p),code=`${a.code}.${a.objectives.length+1}`;a.objectives.push({code,name,strategies:[]})}if(kind==='strategy'){let o=objectives().find(x=>x.code===p),code=`${o.code}.${o.strategies.length+1}`;o.strategies.push({code,name,lineIds:[]})}if(kind==='line'){let st=data.axes.flatMap(a=>a.objectives).flatMap(o=>o.strategies).find(x=>x.code===p),code=`${st.code}.${st.lineIds.length+1}`,id=Date.now();let obj=code.split('.').slice(0,2).join('.');data.lines.push({id,code,name,objective:obj,strategy:st.code,dep:'',status:'Sin asignar',centerId:null,budget:0});st.lineIds.push(id)}persist();renderView();notice(`${label} creado correctamente.`)})}
function editLine(id){let x=findLine(id);openModal('Asignar línea de acción',`<p><b>${x.code}</b> · ${esc(x.name)}</p><label>Dependencia responsable</label><select id="lineDep"><option value="">Sin asignar</option>${data.dependencies.map(d=>`<option ${x.dep===d?'selected':''}>${esc(d)}</option>`).join('')}</select><p class="form-help">El estatus solo cambia cuando el enlace acepta o rechaza la línea.</p>`,()=>{x.dep=q('#lineDep').value;if(!x.dep){x.status='Sin asignar';x.centerId=null;x.budget=0}persist();renderView();notice('Asignación actualizada.')})}
function review(id){let x=findLine(id);openModal('Responder asignación',`<p><b>${x.code}</b> · ${esc(x.name)}</p><label>Decisión</label><select id="decision"><option value="Aceptar">Aceptar</option><option value="Rechazar">Rechazar</option></select><div id="reasonField" style="display:none"><label>Motivo de rechazo <span class="required">*</span></label><textarea id="reason" placeholder="Explica por qué la dependencia no puede atender esta línea."></textarea></div>`,()=>{let decision=q('#decision').value;if(decision==='Rechazar'&&!q('#reason').value.trim()){notice('El motivo de rechazo es obligatorio.');return false}x.status=decision==='Aceptar'?'Aceptada':'Rechazada';x.reason=decision==='Rechazar'?q('#reason').value.trim():'';if(x.status==='Rechazada'){x.centerId=null;x.budget=0}persist();renderView();notice('Respuesta registrada correctamente.')});q('#decision').onchange=e=>q('#reasonField').style.display=e.target.value==='Rechazar'?'block':'none'}
function setCenter(id){let x=findLine(id);openModal('Asignar centro de costo',`<p><b>${x.code}</b> · ${esc(x.name)}</p><label>Centro de costo del catálogo de Finanzas</label><select id="centerId">${data.centers.map(c=>`<option value="${c.id}" ${x.centerId===c.id?'selected':''}>${c.code} · ${esc(c.name)} — techo $${c.ceiling.toLocaleString('es-MX')}</option>`).join('')}</select><p class="form-help">Este centro quedará vinculado exclusivamente a esta línea. Finanzas podrá asignar presupuesto después de guardar.</p>`,()=>{x.centerId=Number(q('#centerId').value);persist();renderView();notice('Centro de costo vinculado. Completa ahora la ficha técnica.')},'Asignar centro')}
const fields=[['pp','1. Pp',''],['program','2. Nombre del Programa / Proyecto',''],['annual','3. Presupuesto anual',''],['key','4. Clave ID',''],['indicator','5. Nombre del indicador',''],['number','5.1 Número del indicador',''],['objectiveText','6. Objetivo del indicador','wide'],['dimension','7. Dimensión',''],['type','8. Tipo',''],['behavior','9. Comportamiento',''],['frequency','10. Frecuencia de medición',''],['variables','11. Variables del indicador','wide'],['source','12. Fuentes de verificación','wide'],['formula','13. Fórmula de cálculo',''],['unit','14. Unidad de medida',''],['baseline','15. Línea base',''],['goal','16. Meta anual',''],['operation','16.1 Meta operativa',''],['quarterly','16.2 Meta trimestral','wide'],['trafficLight','17. Semaforización','wide'],['glossary','18. Glosario','wide'],['pmd','19. PMD',''],['statePlan','20. Plan estatal de desarrollo',''],['ods','21. ODS',''],['components','22. Componentes','wide'],['responsible','23. Dependencia / Entidad',''],['holder','24. Nombre y firma del titular','']];
function sheetDefault(x){return {pp:data.programs[x.objective]||'',program:data.programs[x.objective]||'',annual:x.budget?`$${x.budget.toLocaleString('es-MX')}`:'',key:x.code,indicator:x.name,number:`${x.objective}.01`,objectiveText:'Describe el resultado que busca medir esta línea de acción.',dimension:'Eficacia',type:'Estratégico',behavior:'Ascendente',frequency:'Trimestral',variables:'V1. Avance alcanzado\nV2. Avance total programado',source:'Reportes institucionales y evidencia documental.',formula:'(V1 / V2) * 100',unit:'Porcentaje',baseline:'0%',goal:'100%',operation:'4 etapas de 25%',quarterly:'T1 25% · T2 50% · T3 75% · T4 100%',glossary:'Conceptos relevantes y definiciones operativas.',pmd:`PMD ${x.objective}`,statePlan:'Plan Estatal de Desarrollo vigente',ods:'ODS por definir',components:x.name,responsible:x.dep,holder:'Titular de la dependencia'}}
function sheetForm(id){let x=findLine(id),values={...sheetDefault(x),...(data.sheets[id]||{})};openModal('Completar ficha técnica',`<p class="form-help">Formulario basado en la Ficha Técnica de Indicadores PbR-SED. Guarda la información para habilitar la vista PDF.</p><div class="sheet-form">${fields.map(([key,label,size])=>`<label class="${size||''}">${label}<textarea data-field="${key}" rows="${size?'3':'1'}">${esc(values[key]||'')}</textarea></label>`).join('')}</div>`,()=>{let s={};qa('[data-field]').forEach(i=>s[i.dataset.field]=i.value.trim());data.sheets[id]=s;persist();renderView();notice('Ficha técnica guardada. La vista PDF ya está disponible.')},'Guardar ficha','wide-modal')}
function pdf(id){let x=findLine(id),s=data.sheets[id];if(!s)return sheetForm(id);openModal('Ficha técnica · Vista previa',`<div class="pdf-sheet"><div class="pdf-top"><div><b>Municipio · Sistema PMD</b><h3>Ficha Técnica</h3><small>Indicadores PbR-SED</small></div><span>${x.code}</span></div><div class="pdf-section">Datos de identificación del indicador</div><div class="pdf-grid"><div><b>1. Pp</b><br>${esc(s.pp)}</div><div class="span2"><b>2. Programa / Proyecto</b><br>${esc(s.program)}</div><div><b>3. Presupuesto anual</b><br>${esc(s.annual)}</div><div><b>4. Clave ID</b><br>${esc(s.key)}</div><div class="span2"><b>5. Nombre del indicador</b><br>${esc(s.indicator)}</div><div><b>5.1 Número</b><br>${esc(s.number)}</div><div class="span4"><b>6. Objetivo del indicador</b><br>${esc(s.objectiveText)}</div></div><div class="pdf-section">Método de cálculo del indicador</div><div class="pdf-grid"><div class="span2"><b>11. Variables</b><br>${esc(s.variables).replace(/\n/g,'<br>')}</div><div class="span2"><b>12. Fuentes de verificación</b><br>${esc(s.source)}</div><div><b>13. Fórmula</b><br>${esc(s.formula)}</div><div><b>14. Unidad</b><br>${esc(s.unit)}</div><div><b>15. Línea base</b><br>${esc(s.baseline)}</div><div><b>16. Meta</b><br>${esc(s.goal)}</div></div><div class="pdf-section">Alineación y responsable</div><div class="pdf-grid"><div><b>19. PMD</b><br>${esc(s.pmd)}</div><div><b>20. Plan estatal</b><br>${esc(s.statePlan)}</div><div><b>21. ODS</b><br>${esc(s.ods)}</div><div><b>23. Dependencia</b><br>${esc(s.responsible)}</div><div class="span3"><b>24. Responsable</b><br>${esc(s.holder)}</div></div><span class="pdf-stamp">VISTA SIMULADA · LISTA PARA DESCARGA</span></div>`,()=>notice('La ficha técnica se envió a descarga (simulada).'),'Descargar PDF','wide-modal')}
function bind(){qa('.go-catalog').forEach(b=>b.onclick=()=>{view='catalog';renderApp()});qa('.tree-toggle').forEach(b=>b.onclick=()=>qa('.pivot-wrap .pivot').forEach(n=>n.open=b.dataset.mode==='open'));qa('.add-node').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();nodeForm(b.dataset.kind,b.dataset.parent)});qa('.edit-line').forEach(b=>b.onclick=()=>editLine(b.dataset.id));qa('.line-check').forEach(i=>i.onchange=()=>{let id=Number(i.dataset.id);picked=i.checked?[...new Set([...picked,id])]:picked.filter(x=>x!==id)});if(q('#assignSelected'))q('#assignSelected').onclick=()=>{let dep=q('#assignDep').value;if(!dep||!picked.length){notice('Selecciona una dependencia y al menos una línea.');return}picked.forEach(id=>{let x=findLine(id);x.dep=dep;x.status='Sin asignar';x.centerId=null;x.budget=0});picked=[];persist();renderView();notice('Líneas asignadas al enlace de la dependencia.')};if(q('#addUser'))q('#addUser').onclick=()=>openModal('Crear usuario enlace',`<label>Nombre completo</label><input id="uName"><label>Dependencia</label><select id="uDep">${data.dependencies.map(d=>`<option>${esc(d)}</option>`).join('')}</select><label>Correo</label><input id="uMail" type="email"><label>Contraseña temporal</label><input id="uPass" type="text" placeholder="Ej. Enlace2026!">`,()=>{let name=q('#uName').value.trim(),pass=q('#uPass').value.trim();if(!name||!pass){notice('Nombre y contraseña son obligatorios.');return false}data.users.push({id:Date.now(),name,dep:q('#uDep').value,mail:q('#uMail').value.trim(),password:pass});persist();renderView();notice('Usuario enlace creado; comparte su contraseña temporal de forma segura.')});qa('.del-user').forEach(b=>b.onclick=()=>{data.users=data.users.filter(x=>x.id!==Number(b.dataset.id));persist();renderView();notice('Usuario eliminado.')});if(q('#addDep'))q('#addDep').onclick=()=>openModal('Nueva dependencia','<label>Nombre de la dependencia</label><input id="depName">',()=>{let name=q('#depName').value.trim();if(!name){notice('Escribe el nombre de la dependencia.');return false}data.dependencies.push(name);persist();renderView();notice('Dependencia creada.')});qa('.review').forEach(b=>b.onclick=()=>review(b.dataset.id));qa('.set-center').forEach(b=>b.onclick=()=>setCenter(b.dataset.id));qa('.sheet').forEach(b=>b.onclick=()=>sheetForm(b.dataset.id));qa('.pdf').forEach(b=>b.onclick=()=>pdf(b.dataset.id));if(q('#addCenter'))q('#addCenter').onclick=()=>openModal('Dar de alta centro de costo','<label>Clave</label><input id="ccCode" placeholder="CC-410"><label>Nombre</label><input id="ccName"><label>Techo presupuestal autorizado</label><input id="ccCeiling" type="number" min="0" step="1000">',()=>{let code=q('#ccCode').value.trim(),name=q('#ccName').value.trim(),ceiling=Number(q('#ccCeiling').value);if(!code||!name||!ceiling){notice('Clave, nombre y techo presupuestal son obligatorios.');return false}data.centers.push({id:Date.now(),code,name,ceiling});persist();renderView();notice('Centro de costo dado de alta.')});qa('.del-center').forEach(b=>b.onclick=()=>{let id=Number(b.dataset.id);if(data.lines.some(x=>x.centerId===id)){notice('No se puede eliminar: tiene líneas de acción vinculadas.');return}data.centers=data.centers.filter(x=>x.id!==id);persist();renderView();notice('Centro de costo eliminado.')});if(q('#savePrograms'))q('#savePrograms').onclick=()=>{qa('.program').forEach(i=>data.programs[i.dataset.id]=i.value.trim());persist();renderView();notice('Programas presupuestarios guardados.')};qa('.budget-input').forEach(i=>i.onchange=()=>{let x=findLine(i.dataset.id),value=Number(i.value),c=cc(x.centerId),max=c.ceiling-usedCenter(c.id,x.id);if(value<0||value>max){i.value=x.budget;notice(`El monto supera el disponible de ${c.code}: $${max.toLocaleString('es-MX')}.`);return}x.budget=value;persist();renderView();notice('Presupuesto de línea actualizado.')})}
function enlaceTree(){let rows=ownLines();return head('Estructura PMD asignada',`Responde las líneas remitidas a ${esc(session.dep)}`)+`<div class="two-col"><section class="pivot-wrap compact"><details class="pivot axis" open><summary><span class="chevron">›</span><span class="pivot-code">PMD</span><b>${esc(session.dep)}</b><small>${rows.length} línea(s) asignada(s)</small></summary><div class="pivot-body">${rows.map(x=>`<article class="pivot-line"><span class="pivot-code">${x.code}</span><span class="line-name">${esc(x.name)}</span>${badge(x.status)}<button class="outline review" data-id="${x.id}">${x.status==='Sin asignar'?'Responder':'Ver respuesta'}</button></article>`).join('')||'<p class="empty">No hay líneas asignadas a esta dependencia.</p>'}</div></details></section><section class="panel"><h3>Acciones del enlace</h3><p class="panel-sub">Acepta si tu dependencia puede atender la línea; al rechazar, el motivo es obligatorio.</p><div class="activity"><i class="dot orange"></i><span>Una línea aceptada debe tener centro de costo antes de ser presupuestada.</span></div><div class="activity"><i class="dot"></i><span>El presupuesto permanece bloqueado para Finanzas mientras no se asigne el centro de costo.</span></div></section></div>`}
document.addEventListener('click',e=>{let button=e.target.closest('#addUser');if(!button)return;e.preventDefault();e.stopImmediatePropagation();openModal('Crear usuario enlace',`<label>Nombre completo</label><input id="uName"><label>Usuario</label><input id="uUsername" placeholder="Ej. m.lopez"><label>Dependencia</label><select id="uDep">${data.dependencies.map(d=>`<option>${esc(d)}</option>`).join('')}</select><label>Correo</label><input id="uMail" type="email"><label>Contraseña temporal</label><input id="uPass" type="text" placeholder="Ej. Enlace2026!">`,()=>{let name=q('#uName').value.trim(),username=q('#uUsername').value.trim().toLowerCase(),dep=q('#uDep').value,pass=q('#uPass').value.trim();if(!name||!username||!pass){notice('Nombre, usuario y contraseña son obligatorios.');return false}if(data.users.some(u=>u.username.toLowerCase()===username)){notice('Ese nombre de usuario ya está en uso.');return false}if(data.users.some(u=>u.dep===dep)){notice('Esta dependencia ya tiene un enlace asignado.');return false}data.users.push({id:Date.now(),name,username,dep,mail:q('#uMail').value.trim(),password:pass});persist();renderView();notice('Usuario enlace creado; comparte sus credenciales de forma segura.')})},true);
login();

/* Catálogos PMD: filtros compartidos e historial de rechazos */
nav.Finanzas[0][1]='Catálogo PMD';
titles.finance='Catálogo PMD';
let pmdFilters={admin:{status:'',dependency:''},finance:{status:'',dependency:''}};
function matchesPmdFilter(line,filters){return (!filters.status||line.status===filters.status)&&(!filters.dependency||line.dep===filters.dependency)}
function pmdFiltersBar(scope){let filters=pmdFilters[scope];return `<section class="pmd-filter-bar"><div><b>Filtrar líneas de acción</b><small>Los filtros se aplican a toda la estructura jerárquica.</small></div><label>Estatus<select data-pmd-scope="${scope}" data-pmd-filter="status"><option value="">Todos los estatus</option><option value="Sin asignar" ${filters.status==='Sin asignar'?'selected':''}>Sin asignar</option><option value="Aceptada" ${filters.status==='Aceptada'?'selected':''}>Aceptada</option><option value="Rechazada" ${filters.status==='Rechazada'?'selected':''}>Rechazada</option></select></label><label>Dependencia<select data-pmd-scope="${scope}" data-pmd-filter="dependency"><option value="">Todas las dependencias</option><option value="Sin dependencia" ${filters.dependency==='Sin dependencia'?'selected':''}>Sin dependencia</option>${data.dependencies.map(dep=>`<option value="${esc(dep)}" ${filters.dependency===dep?'selected':''}>${esc(dep)}</option>`).join('')}</select></label></section>`}
function matchesPmdFilterWithEmpty(line,filters){let dependency=filters.dependency==='Sin dependencia'?'':filters.dependency;return matchesPmdFilter(line,{...filters,dependency})}
function pivot(filters={},editable=true){let axesHtml=data.axes.map(axis=>{let objectivesHtml=axis.objectives.map(obj=>{let strategiesHtml=obj.strategies.map(st=>{let visible=linesOf(st).filter(line=>matchesPmdFilterWithEmpty(line,filters));if(!visible.length)return '';return `<details class="pivot strategy" open><summary><span class="chevron">›</span><span class="pivot-code">${st.code}</span><b>${esc(st.name)}</b><small>${visible.length} línea(s)</small>${editable?`<button class="mini-btn add-node" data-kind="line" data-parent="${st.code}">＋ Línea</button>`:''}</summary><div class="pivot-body line-list">${visible.map(line=>`<article class="pivot-line"><span class="pivot-code">${line.code}</span><span class="line-name">${esc(line.name)}</span><span>${badge(line.status)}</span><span class="line-dep">${line.dep||'Sin dependencia'}</span>${editable?`<button class="outline edit-line" data-id="${line.id}">Asignar</button>`:''}</article>`).join('')}</div></details>`}).join('');if(!strategiesHtml)return '';return `<details class="pivot objective" open><summary><span class="chevron">›</span><span class="pivot-code">${obj.code}</span><b>${esc(obj.name)}</b><small>${obj.strategies.length} estrategia(s)</small>${editable?`<button class="mini-btn add-node" data-kind="strategy" data-parent="${obj.code}">＋ Estrategia</button>`:''}</summary><div class="pivot-body">${strategiesHtml}</div></details>`}).join('');if(!objectivesHtml)return '';return `<details class="pivot axis" open><summary><span class="chevron">›</span><span class="pivot-code">${axis.code}</span><b>${esc(axis.name)}</b><small>${axis.objectives.length} objetivo(s)</small>${editable?`<button class="mini-btn add-node" data-kind="objective" data-parent="${axis.code}">＋ Objetivo</button>`:''}</summary><div class="pivot-body">${objectivesHtml}</div></details>`}).join('');return axesHtml||'<p class="empty">No hay líneas de acción que coincidan con los filtros seleccionados.</p>'}
function rejectionEntries(filters){return data.lines.flatMap(line=>{let records=line.rejectionHistory||[];if(!records.length&&line.status==='Rechazada'&&line.reason)records=[{name:'Registro anterior',dependency:line.dep||'No disponible',reason:line.reason,at:'Sin fecha'}];return records.map(record=>({line,record}))}).filter(item=>matchesPmdFilterWithEmpty(item.line,filters)).sort((a,b)=>String(b.record.at).localeCompare(String(a.record.at)))}
function rejectionHistory(filters){let entries=rejectionEntries(filters);return `<section class="rejection-history"><div class="history-heading"><div><h3>Historial de rechazos</h3><p>Consulta quién rechazó cada línea, la dependencia responsable y el motivo indicado.</p></div><span class="history-count">${entries.length} registro(s)</span></div>${entries.length?`<div class="history-list">${entries.map(({line,record})=>`<article class="history-item"><div class="history-code">${line.code}</div><div><b>${esc(line.name)}</b><p><strong>${esc(record.name)}</strong> · ${esc(record.dependency)} · ${esc(record.at)}</p><blockquote>${esc(record.reason)}</blockquote></div></article>`).join('')}</div>`:'<p class="empty">No hay rechazos que coincidan con los filtros seleccionados.</p>'}</section>`}
function catalog(){let filters=pmdFilters.admin;let visibleLines=data.lines.filter(line=>matchesPmdFilterWithEmpty(line,filters));return head('Catálogo PMD','Una única estructura jerárquica para crear, consultar, filtrar y asignar el plan',`<div class="section-toolbar"><button class="outline tree-toggle" data-mode="open">Expandir todo</button><button class="outline tree-toggle" data-mode="close">Comprimir todo</button><button class="outline add-node" data-kind="axis">＋ Eje</button><button class="primary add-node" data-kind="line">＋ Línea de acción</button></div>`)+pmdFiltersBar('admin')+`<div class="catalog-note"><b>Vista pivote:</b> expande o comprime Ejes, Objetivos, Estrategias y Líneas de acción. Cada línea conserva su estatus y responsable.</div><div class="status-legend">${badge('Sin asignar')} ${badge('Aceptada')} ${badge('Rechazada')}</div><section class="pivot-wrap">${pivot(filters,true)}</section>${rejectionHistory(filters)}<section class="assignment-box"><div><h3>Asignar líneas a dependencia</h3><p>Selecciona una o varias líneas visibles; el enlace de la dependencia podrá responderlas.</p></div><div class="assign-controls"><select id="assignDep"><option value="">Selecciona una dependencia</option>${data.dependencies.map(d=>`<option>${esc(d)}</option>`).join('')}</select><button class="primary" id="assignSelected">Asignar seleccionadas</button></div><div class="assign-lines">${visibleLines.map(x=>`<label><input class="line-check" data-id="${x.id}" type="checkbox" ${picked.includes(x.id)?'checked':''}><span class="pivot-code">${x.code}</span> ${esc(x.name)} <em>${x.dep||'Sin dependencia'}</em></label>`).join('')||'<p class="empty">No hay líneas disponibles con estos filtros.</p>'}</div></section>`}
function finance(){let filters=pmdFilters.finance;return head('Catálogo PMD','Consulta la estructura estratégica aprobada y filtra las líneas por estatus o dependencia')+pmdFiltersBar('finance')+`<section class="pivot-wrap readonly">${pivot(filters,false)}</section><div class="catalog-note">Consulta la estructura. Los centros de costo y presupuestos se gestionan desde las opciones del menú.</div>`}
function review(id){let line=findLine(id);openModal('Responder asignación',`<p><b>${line.code}</b> · ${esc(line.name)}</p><label>Decisión</label><select id="decision"><option value="Aceptar">Aceptar</option><option value="Rechazar">Rechazar</option></select><div id="reasonField" style="display:none"><label>Motivo de rechazo <span class="required">*</span></label><textarea id="reason" placeholder="Explica por qué la dependencia no puede atender esta línea."></textarea></div>`,()=>{let decision=q('#decision').value,reason=q('#reason').value.trim();if(decision==='Rechazar'&&!reason){notice('El motivo de rechazo es obligatorio.');return false}line.status=decision==='Aceptar'?'Aceptada':'Rechazada';if(decision==='Rechazar'){line.reason=reason;line.centerId=null;line.budget=0;line.rejectionHistory=line.rejectionHistory||[];line.rejectionHistory.unshift({name:session.name,username:session.username,dependency:session.dep,reason,at:new Date().toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'})})}persist();renderView();notice('Respuesta registrada correctamente.')});q('#decision').onchange=e=>q('#reasonField').style.display=e.target.value==='Rechazar'?'block':'none'}
document.addEventListener('change',e=>{let target=e.target;if(!target.matches('[data-pmd-filter]'))return;let scope=target.dataset.pmdScope,key=target.dataset.pmdFilter;pmdFilters[scope][key]=target.value;renderView()});

function pmdImportOpen(){return data.demoMode||new Date().getMonth()===0}
function catalog(){let filters=pmdFilters.admin,visibleLines=data.lines.filter(line=>matchesPmdFilterWithEmpty(line,filters)),canImport=pmdImportOpen();return head('Catálogo PMD','Estructura estratégica anual del Plan Municipal de Desarrollo',`<div class="section-toolbar"><button class="outline tree-toggle" data-mode="open">Expandir todo</button><button class="outline tree-toggle" data-mode="close">Comprimir todo</button><button class="outline add-node" data-kind="axis">＋ Eje</button><button class="primary" id="pmdImport" ${canImport?'':'disabled'}>Importar Excel PMD</button><input id="pmdImportFile" type="file" accept=".xlsx" hidden></div>`)+`<div class="annual-load-note ${canImport?'enabled':''}"><b>${canImport?'Carga de estructura habilitada':'Carga de estructura cerrada'}</b><span>La estructura PMD se carga únicamente del 1 al 31 de enero.</span></div>`+pmdFiltersBar('admin')+`<div class="catalog-note"><b>Vista pivote:</b> expande o comprime Ejes, Objetivos, Estrategias y Líneas de acción. Cada línea conserva su estatus y responsable.</div><div class="status-legend">${badge('Sin asignar')} ${badge('Aceptada')} ${badge('Rechazada')}</div><section class="pivot-wrap">${pivot(filters,true)}</section>${rejectionHistory(filters)}<section class="assignment-box"><div><h3>Asignar líneas a dependencia</h3><p>Selecciona una o varias líneas visibles; el enlace de la dependencia podrá responderlas.</p></div><div class="assign-controls"><select id="assignDep"><option value="">Selecciona una dependencia</option>${data.dependencies.map(d=>`<option>${esc(d)}</option>`).join('')}</select><button class="primary" id="assignSelected">Asignar seleccionadas</button></div><div class="assign-lines">${visibleLines.map(x=>`<label><input class="line-check" data-id="${x.id}" type="checkbox" ${picked.includes(x.id)?'checked':''}><span class="pivot-code">${x.code}</span> ${esc(x.name)} <em>${x.dep||'Sin dependencia'}</em></label>`).join('')||'<p class="empty">No hay líneas disponibles con estos filtros.</p>'}</div></section>`}
function cleanKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase()}
function xlsxCol(ref){return ref.replace(/\d/g,'').split('').reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1}
async function unzipXlsx(buffer){let view=new DataView(buffer),bytes=new Uint8Array(buffer),eocd=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(view.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('El archivo no tiene una estructura XLSX válida.');let total=view.getUint16(eocd+10,true),pos=view.getUint32(eocd+16,true),out={};for(let i=0;i<total;i++){if(view.getUint32(pos,true)!==0x02014b50)throw new Error('No fue posible leer el contenido del Excel.');let method=view.getUint16(pos+10,true),size=view.getUint32(pos+20,true),nameLen=view.getUint16(pos+28,true),extraLen=view.getUint16(pos+30,true),commentLen=view.getUint16(pos+32,true),offset=view.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nameLen)),localName=view.getUint16(offset+26,true),localExtra=view.getUint16(offset+28,true),start=offset+30+localName+localExtra,raw=bytes.slice(start,start+size);if(method===8){let stream=new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'));raw=new Uint8Array(await new Response(stream).arrayBuffer())}else if(method!==0)throw new Error('Método de compresión no compatible.');out[name]=new TextDecoder().decode(raw);pos+=46+nameLen+extraLen+commentLen}return out}
function xlsxRows(xml,shared){let doc=new DOMParser().parseFromString(xml,'application/xml'),rows=[];for(let row of [...doc.getElementsByTagName('row')]){let values=[];for(let cell of [...row.getElementsByTagName('c')]){let col=xlsxCol(cell.getAttribute('r')),type=cell.getAttribute('t'),value='';if(type==='inlineStr')value=cell.textContent||'';else{let v=cell.getElementsByTagName('v')[0]?.textContent||'';value=type==='s'?(shared[Number(v)]||''):v}values[col]=value}rows.push(values)}let headers=(rows.shift()||[]).map(x=>String(x||'').trim());return rows.filter(r=>r.some(v=>v!==undefined&&v!=='')).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
function tableField(row,key){let found=Object.keys(row).find(k=>cleanKey(k)===key);return found?String(row[found]??'').trim():''}
function buildPmdStructure(tables){let deps=(tables.iddependencia||[]).map(r=>({id:tableField(r,'iddependencia'),name:tableField(r,'dependencia')})).filter(x=>x.id);let axisRows=tables.ideje||[],objRows=tables.idobjetivo||[],stratRows=tables.idestrategia||[],lineRows=tables.idlinea||[],ppRows=tables.idpp||[];let pp=new Map(ppRows.map(r=>[tableField(r,'idpp'),{name:tableField(r,'nombrepp'),type:tableField(r,'tipopp')}])) ,axes=axisRows.map(r=>({code:tableField(r,'ideje'),name:tableField(r,'eje'),objectives:[]})).filter(x=>x.code),axisMap=new Map(axes.map(x=>[x.code,x]));let objMap=new Map();objRows.forEach(r=>{let axis=tableField(r,'ideje'),code=tableField(r,'idobjetivo');if(axisMap.has(axis)&&code){let o={code,name:tableField(r,'nombreobjetivo'),strategies:[]};axisMap.get(axis).objectives.push(o);objMap.set(code,o)}});let stratMap=new Map();stratRows.forEach(r=>{let obj=tableField(r,'idobjetivo'),code=tableField(r,'idestrategia');if(objMap.has(obj)&&code){let s={code,name:tableField(r,'nombreestrategia'),lineIds:[]};objMap.get(obj).strategies.push(s);stratMap.set(code,s)}});let lines=lineRows.map((r,i)=>{let ppid=tableField(r,'idpp'),strategy=tableField(r,'idestrategia'),line={id:i+1,code:tableField(r,'idlinea'),name:tableField(r,'lineadeaccion'),axis:tableField(r,'ideje'),objective:tableField(r,'idobjetivo'),strategy,programId:ppid,programName:pp.get(ppid)?.name||'',programType:pp.get(ppid)?.type||'',executionYear:tableField(r,'anoejecucion'),manualYear:tableField(r,'anoejecucionmanual'),dependencyId:tableField(r,'iddependencia'),dep:tableField(r,'dependencia'),status:'Sin asignar',centerId:null,budget:0,rejectionHistory:[]};stratMap.get(strategy)?.lineIds.push(line.id);return line}).filter(x=>x.code);return {dependencies:deps.map(x=>x.name),dependencyCatalog:deps,axes,lines,programCatalog:[...pp].map(([id,v])=>({id,...v}))}}
async function importPmdExcel(file){if(!file)return;if(!pmdImportOpen()){notice('La carga de estructura está permitida únicamente durante enero.');return}try{let files=await unzipXlsx(await file.arrayBuffer()),sharedDoc=files['xl/sharedStrings.xml']?new DOMParser().parseFromString(files['xl/sharedStrings.xml'],'application/xml'):null,shared=sharedDoc?[...sharedDoc.getElementsByTagName('si')].map(x=>x.textContent||''):[],wb=new DOMParser().parseFromString(files['xl/workbook.xml'],'application/xml'),rels=new DOMParser().parseFromString(files['xl/_rels/workbook.xml.rels'],'application/xml'),relations=Object.fromEntries([...rels.getElementsByTagName('Relationship')].map(r=>[r.getAttribute('Id'),r.getAttribute('Target')])),tables={};for(let sheet of [...wb.getElementsByTagName('sheet')]){let key=cleanKey(sheet.getAttribute('name')),rid=sheet.getAttribute('r:id')||sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),target=relations[rid],path='xl/'+target.replace(/^\//,'');tables[key]=xlsxRows(files[path],shared)}let structure=buildPmdStructure(tables);if(!structure.lines.length||!structure.axes.length)throw new Error('No se encontraron las tablas Id_Eje, Id_Objetivo, Id_Estrategia e Id_Línea.');Object.assign(data,{...structure,programs:{},sheets:{},importedAt:new Date().toLocaleString('es-MX'),importedFrom:file.name});picked=[];pmdFilters={admin:{status:'',dependency:''},finance:{status:'',dependency:''}};persist();renderView();notice(`Se importaron ${structure.lines.length} líneas de acción desde ${file.name}.`)}catch(error){notice(error.message||'No fue posible importar el Excel seleccionado.')}}
document.addEventListener('click',e=>{if(e.target.closest('#pmdImport'))q('#pmdImportFile')?.click()});
document.addEventListener('change',e=>{if(e.target.id==='pmdImportFile')importPmdExcel(e.target.files[0])});

function sheetDefault(x){return {pp:x.programId||data.programs[x.objective]||'',program:x.programName||data.programs[x.objective]||'',annual:x.budget?`$${x.budget.toLocaleString('es-MX')}`:'',key:x.code,indicator:x.name,number:`${x.programId||x.objective}.01`,objectiveText:'Describe el resultado que busca medir esta línea de acción.',dimension:'Eficacia',type:'Estratégico',behavior:'Ascendente',frequency:'Trimestral',variables:'V1. Avance alcanzado\nV2. Avance total programado',source:'Reportes institucionales y evidencia documental.',formula:'(V1 / V2) * 100',unit:'Porcentaje',baseline:'0%',goal:'100%',operation:'4 etapas de 25%',quarterly:'T1 25% · T2 50% · T3 75% · T4 100%',trafficLight:'Verde: 90% a 100% · Amarillo: 70% a 89% · Rojo: menor a 70%',glossary:'Conceptos relevantes y definiciones operativas.',pmd:`PMD ${x.objective}`,statePlan:'Plan Estatal de Desarrollo vigente',ods:'ODS por definir',components:x.name,responsible:x.dep,holder:'Titular de la dependencia'}}
function fichaMarkup(line,s){let cell=(label,value,wide='')=>`<div class="ficha-cell ${wide}"><b>${label}</b><span>${esc(value||'').replace(/\n/g,'<br>')}</span></div>`;return `<article class="ficha-document"><header><div><strong>Municipio de Guadalupe, Nuevo León</strong><h2>Ficha Técnica</h2><small>Indicadores PbR-SED</small></div><span>${esc(line.code)}</span></header><h3>Datos de Identificación del Indicador</h3><section class="ficha-grid">${cell('1. Pp',s.pp)}${cell('2. Nombre del Programa / Proyecto',s.program,'span2')}${cell('3. Presupuesto Anual',s.annual)}${cell('4. Clave ID',s.key)}${cell('5. Nombre del Indicador',s.indicator,'span2')}${cell('5.1 Número del indicador',s.number)}${cell('6. Objetivo del Indicador',s.objectiveText,'span4')}${cell('7. Dimensión',s.dimension)}${cell('8. Tipo',s.type)}${cell('9. Comportamiento',s.behavior)}${cell('10. Frecuencia de Medición',s.frequency)}</section><h3>Método de Cálculo del Indicador</h3><section class="ficha-grid">${cell('11. Variables del Indicador',s.variables,'span2')}${cell('12. Fuentes de Verificación',s.source,'span2')}${cell('13. Fórmula de Cálculo',s.formula)}${cell('14. Unidad de Medida',s.unit)}${cell('15. Línea Base',s.baseline)}${cell('16. Meta anual',s.goal)}${cell('16.1 Meta operativa',s.operation,'span2')}${cell('16.2 Meta trimestral',s.quarterly,'span2')}${cell('17. Semaforización',s.trafficLight,'span4')}${cell('18. Glosario',s.glossary,'span4')}</section><h3>Alineación del Indicador</h3><section class="ficha-grid">${cell('19. PMD',s.pmd)}${cell('20. Plan Estatal de Desarrollo',s.statePlan,'span2')}${cell('21. ODS',s.ods)}${cell('22. Componentes',s.components,'span4')} ${cell('23. Dependencia / Entidad',s.responsible,'span2')}${cell('24. Nombre y Firma del Titular',s.holder,'span2')}</section></article>`}
function printTechnicalSheet(id){let line=findLine(id),s=data.sheets[id],popup=window.open('','_blank','width=1050,height=850');if(!popup){notice('Permite las ventanas emergentes para imprimir o descargar la ficha.');return}let due=new Date();due.setDate(due.getDate()+7);line.signatureRequest=line.signatureRequest||{due:due.toLocaleDateString('es-MX'),status:'Pendiente'};persist();popup.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Ficha Técnica ${esc(line.code)}</title><style>body{font-family:Arial,sans-serif;margin:20px;color:#151d25}.ficha-document{max-width:1000px;margin:auto}.ficha-document header{display:flex;justify-content:space-between;align-items:start;text-align:center;color:#ef7d19;border-bottom:2px solid #ef7d19;padding:0 12px 12px}.ficha-document header h2{margin:4px 0}.ficha-document h3{text-align:center;background:#e9e9e9;border:1px solid #222;margin:14px 0 0;padding:6px;font-size:13px}.ficha-grid{display:grid;grid-template-columns:repeat(4,1fr);border-left:1px solid #222}.ficha-cell{min-height:56px;border-right:1px solid #222;border-bottom:1px solid #222;font-size:10px;line-height:1.35}.ficha-cell b{display:block;background:#ef7d19;color:white;padding:4px;font-size:10px}.ficha-cell span{display:block;padding:6px}.span2{grid-column:span 2}.span4{grid-column:span 4}@media print{body{margin:8mm}.ficha-document{max-width:none}}</style></head><body>${fichaMarkup(line,s)}<script>window.onload=()=>window.print()<\/script></body></html>`);popup.document.close();setTimeout(()=>signatureAlert(id),250)}
function signatureAlert(id){let line=findLine(id),request=line.signatureRequest||{};openModal('Seguimiento de ficha firmada',`<p>La ficha técnica <b>${esc(line.name)}</b> tiene como límite <b>${esc(request.due||'7 días')}</b> para subirla firmada.</p><label>¿La ficha técnica está firmada?</label><select id="signedStatus"><option value="Pendiente" ${request.status==='Pendiente'?'selected':''}>Pendiente</option><option value="Sí" ${request.status==='Sí'?'selected':''}>Sí</option><option value="No" ${request.status==='No'?'selected':''}>No</option></select><label>Adjuntar ficha firmada (PDF)</label><input id="signedFile" type="file" accept="application/pdf">${request.fileName?`<small class="form-help">Archivo registrado: ${esc(request.fileName)}</small>`:''}`,()=>{let file=q('#signedFile').files[0];line.signatureRequest={...request,status:q('#signedStatus').value,fileName:file?.name||request.fileName||''};persist();renderView();notice(file?'Ficha firmada registrada y seguimiento actualizado.':'Seguimiento de firma actualizado.')},'Guardar respuesta')}
function pdf(id){let line=findLine(id),s=data.sheets[id];if(!s)return sheetForm(id);openModal('Ficha técnica · Vista previa',`${fichaMarkup(line,s)}<p class="print-help">Al continuar se abrirá la ventana de impresión. Selecciona “Guardar como PDF” para descargar el documento.</p>`,()=>printTechnicalSheet(id),'Imprimir / Guardar PDF','wide-modal')}
